import { useEffect, useState } from 'react'
import TopNavBack from '../components/TopNavBack'
import { buscarFidelidade, buscarHistoricoFidelidade } from '../services/api'
export default function Fidelidade(){const [dados,setDados]=useState(null),[historico,setHistorico]=useState([]),[erro,setErro]=useState('');useEffect(()=>{Promise.all([buscarFidelidade(),buscarHistoricoFidelidade()]).then(([d,h])=>{setDados(d);setHistorico(h)}).catch(e=>setErro(e.message))},[]);return <div className="app-frame"><TopNavBack title="Fidelidade" to="/perfil"/><div className="content">{erro&&<div style={{color:'#d32f2f'}}>{erro}</div>}{dados&&<div className="card" style={{textAlign:'center',marginBottom:18}}><div style={{fontSize:12,color:'#8A867C'}}>Seus pontos</div><div style={{fontSize:42,fontWeight:900,color:'var(--basil)'}}>{dados.pontosSaldo}</div><div style={{fontSize:12,color:'#8A867C'}}>Você acumula {dados.pontosPorReal} ponto(s) por R$ 1 em pedidos finalizados.</div></div>}<div className="section-title">Histórico</div><div className="card">{historico.length===0?<div className="empty-state">Nenhuma movimentação ainda.</div>:historico.map(m=><div className="list-row" key={m.id}><div style={{flex:1}}><div>{m.descricao}</div><div style={{fontSize:11,color:'#8A867C'}}>{new Date(m.criadoEm).toLocaleString('pt-BR')}</div></div><strong style={{color:m.tipo==='CREDITO'?'var(--basil)':'#d32f2f'}}>{m.tipo==='CREDITO'?'+':'-'}{m.pontos}</strong></div>)}</div></div></div>}
